dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "mixed"
        }
      ]
    },
    {
      "parameter": "cohort",
      "label": "Cohort",
      "type": "list",
      "values": [
        {
          "label": "AoUv8",
          "value": "AoUv8"
        },
        {
          "label": "MGB",
          "value": "MGB"
        },
        {
          "label": "UKB",
          "value": "UKB"
        },
        {
          "label": "AoUv8_MGB",
          "value": "AoUv8_MGB"
        },
        {
          "label": "UKB_AoUv8",
          "value": "UKB_AoUv8"
        },
        {
          "label": "UKB_MGB",
          "value": "UKB_MGB"
        },
        {
          "label": "UKB_AoUv8_MGB",
          "value": "UKB_AoUv8_MGB"
        }
      ]
    },
    {
      "parameter": "gene",
      "label": "Phenotypes by Gene",
      "type": "input",
      "values": "kp genes"
    },
    {
      "parameter": "phenotype",
      "label": "Phenotype for Associations",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "file",
      "label": "File",
      "type": "list",
      "values": [
        {
          "label": "600 Traits",
          "value": "https://hugeampkpncms.org/sites/default/files/phenotypes_with_labels.csv"
        }
      ],
      "display": "false"
    }
  ],
  "tab groups": [
    {
      "label": "Section",
      "sections": [
        {
          "section": "traitsByGene",
          "label": "Phenotypes by Gene"
        },
        {
          "section": "traitsList",
          "label": "Phenotypes Full List"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "traitsList",
      "header": "Phenotypes List",
      "data point": {
        "type": "file",
        "parameter": "file",
        "initial load": "https://hugeampkpncms.org/sites/default/files/phenotypes_with_labels.csv",
        "data type": "csv"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
	  {
            "type": "raw",
            "field name": "Description",
            "raw field": "description"
          },
	  {
            "type": "raw",
            "field name": "Group",
            "raw field": "group"
          }
        ],
        "column formatting": {
          "Phenotype": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Search Phenotype",
                "parameter": [
                  "phenotype"
                ]
              }
            ]
          }
        },
        "top rows": [
          "Phenotype",
          "Description",
          "Group"
        ]
      },
      "filters": [
        {
          "field": "Phenotype",
          "label": "Phenotype code",
          "type": "search"
        },
        {
          "field": "Description",
          "label": "Description",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Group",
          "label": "Group",
          "type": "checkbox"
        }
      ]
    },
    {
      "section id": "traitsByGene",
      "header": "Phenotypes List by Gene",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "gene-associations-600trait_v2",
        "parameters": [
          "ancestry",
          "cohort",
          "gene"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Set Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "replace characters",
            "field name": "Meaning",
            "raw field": "phenotypeMeaning",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          },
          {
            "type": "replace characters",
            "field name": "Category",
            "raw field": "phenotypeCategory",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          },
          {
            "type": "kp phenotype name",
            "field name": "Phenotype name",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "ID",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue",
            "if no value": 1
          },
          {
            "type": "raw",
            "field name": "P-Value: Rare",
            "raw field": "pValue_rare",
            "if no value": 1
          },
          {
            "type": "raw",
            "field name": "P-Value: Low Freq",
            "raw field": "pValue_low_freq",
            "if no value": 1
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Masks",
            "raw field": "masks"
          },
          {
            "type": "raw",
            "field name": "Mask",
            "raw field": "mask"
          },
          {
            "type": "raw",
            "field name": "Effective Sample Size",
            "raw field": "n"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Combined AF",
            "raw field": "combinedAF"
          },
          {
            "type": "raw",
            "field name": "Cases",
            "raw field": "cases"
          },
          {
            "type": "raw",
            "field name": "Controls",
            "raw field": "controls"
          }
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ],
            "percent if empty": 1
          },
          "P-Value: Rare": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ],
            "percent if empty": 1
          },
          "P-Value: Low Freq": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ],
            "percent if empty": 1
          },
          "Beta": {
            "type": [
              "fixed 4",
              "direction triangle"
            ]
          },
          "Effective Sample Size": {
            "type": [
              "js math"
            ],
            "method": "round"
          },
          "Combined AF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Phenotype": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Search Phenotype",
                "parameter": [
                  "phenotype"
                ]
              }
            ]
          }
        },
        "top rows": [
          "Phenotype",
          "Category",
          "Meaning",
          "P-Value: Rare",
          "P-Value: Low Freq",
          "Beta"
        ],
         "tool tips": {
          "P-Value: Rare": "Cauchy p-value of the gene-level association from rare and ultra-rare masks. 1 indicates missing data",
          "P-Value: Low Freq": "Cauchy p-value of the gene-level association from low-frequency, rare and ultra-rare masks. 1 indicates missing data",
          "Beta": "Effect size from mask with the lowest p-value"
        },
        "features": [
          "Masks"
        ],
        "Masks": [
          "Mask",
          "P-Value",
          "Combined AF",
          "Standard Error",
          "Effective Sample Size",
          "Cases",
          "Controls",
          "Beta"
        ]
      },
      "filters": [
        {
          "field": "Phenotype name",
          "label": "Phenotype",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Meaning",
          "label": "Meaning",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Category",
          "label": "Category",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        }
      ],
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "P-Value: Rare",
            "type": "phewas plot",
            "group by": "Category",
            "y axis field": "P-Value: Rare",
            "convert y -log10": "true",
            "y ticks decimal point": "2",
            "render by": "Meaning",
            "y axis label": "-Log10(P-Value: Rare)",
            "x axis label": "Beta",
            "beta field": "Beta",
            "hover content": [
              "P-Value: Rare",
              "Beta"
            ],
            "thresholds": [
              "5e-5"
            ],
            "height": 500,
            "star key": "Phenotype",
            "plot margin": {
              "top": 300,
              "bottom": 200,
              "left": 150,
              "right": 175
            }
          },
          {
            "label": "P-Value: Low Freq",
            "type": "phewas plot",
            "group by": "Category",
            "y axis field": "P-Value: Low Freq",
            "convert y -log10": "true",
            "y ticks decimal point": "2",
            "render by": "Meaning",
            "y axis label": "-Log10(P-Value: Low Freq)",
            "x axis label": "Beta",
            "beta field": "Beta",
            "hover content": [
              "P-Value: Low Freq",
              "Beta"
            ],
            "thresholds": [
              "5e-5"
            ],
            "height": 500,
            "star key": "Phenotype",
            "plot margin": {
              "top": 300,
              "bottom": 200,
              "left": 150,
              "right": 175
            }
          }
        ]
      }
    },
    {
      "section id": "phenotypeAssociations",
      "header": "Phenotype Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "gene-finder-600trait_v2",
        "parameters": [
          "ancestry",
          "cohort",
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "lambda",
            "raw field": "lambda"
          },
	  {
            "type": "raw",
            "field name": "lambda_rare",
            "raw field": "lambda_rare"
          },
	        {
            "type": "raw",
            "field name": "lambda_low_freq",
            "raw field": "lambda_low_freq"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Search Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Type",
            "raw field": "type"
          },
          {
            "type": "raw",
            "field name": "Best Mask",
            "raw field": "best_mask"
          },
          {
            "type": "raw",
            "field name": "P-Value: Best Mask",
            "raw field": "pValue_best_mask",
            "if no value": 1
          },
          {
            "type": "raw",
            "field name": "P-Value: Low Freq",
            "raw field": "pValue_low_freq",
            "if no value": 1
          },
          {
            "type": "calculate",
            "field name": "Log10(P-Value: Low Freq)",
            "raw field": "P-Value: Low Freq",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "P-Value: Rare",
            "raw field": "pValue_rare",
            "if no value": 1
          },
          {
            "type": "calculate",
            "field name": "Log10(P-Value: Rare)",
            "raw field": "P-Value: Rare",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Cases",
            "raw field": "cases"
          },
          {
            "type": "raw",
            "field name": "Controls",
            "raw field": "controls"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          }
        ],
        "column formatting": {
          "Gene": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Search Gene",
                "parameter": [
                  "gene"
                ]
              }
            ]
          },
          "P-Value: Best Mask": {
            "type": [
              "scientific notation"
            ]
          },
          "P-Value: Low Freq": {
            "type": [
              "scientific notation"
            ]
          },
          "P-Value: Rare": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "fixed 4",
              "direction triangle"
            ]
          }
        },
        "top rows": [
          "Gene",
          "Region",
          "P-Value: Rare",
          "P-Value: Low Freq",
          "P-Value: Best Mask",
          "Beta",
          "Best Mask",
          "Type",
          "Cases",
          "Controls"
        ],
        "tool tips": {
          "Gene": "Click a gene name to see all associations for that gene",
          "Region": "Chromosome and coordinates of the gene",
          "P-Value: Rare": "Cauchy p-value of the gene-level association from rare and ultra-rare masks. 1 indicates missing data",
          "P-Value: Low Freq": "Cauchy p-value of the gene-level association from low-frequency, rare and ultra-rare masks. 1 indicates missing data",
          "P-Value: Best Mask": "Lowest p-value across all masks. 1 indicates missing data",
          "Beta": "Effect size from mask with the lowest p-value",
          "Best Mask": "Mask with the lowest p-value",
          "Type": "Type of the gene",
          "Phenotype meaning": "Description of the phenotype",
          "Phenotype category": "Broad grouping for the phenotype"
        },
        "locus field": "Region"
      },
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "By P-Value: Rare",
            "type": "manhattan qq plot",
            "x axis field": "Region",
            "y axis field": "Log10(P-Value: Rare)",
	    "lambda": "lambda_rare",
            "render by": "Gene",
            "m-plot y axis label": "-Log10(P-Value: Rare)",
            "m-plot x axis label": "Chromosome",
            "m-plot thresholds": [
              "1e-6"
            ],
            "qq-plot y axis label": "-Log10(P-Value: Rare)",
            "qq-plot x axis label": "Expected -Log10(P-Value) \n Lambda > 1.2: High; > 1.5 Very High",
            "hover content": [
              "Region",
              "P-Value: Rare"
            ],
            "height": 150
          },
          {
            "label": "By P-Value: Low Freq",
            "type": "manhattan qq plot",
            "x axis field": "Region",
            "y axis field": "Log10(P-Value: Low Freq)",
	    "lambda": "lambda_low_freq",
            "render by": "Gene",
            "m-plot y axis label": "-Log10(P-Value: Low Freq)",
            "m-plot x axis label": "Chromosome",
            "m-plot thresholds": [
              "1e-6"
            ],
            "qq-plot y axis label": "-Log10(P-Value: Low Freq)",
            "qq-plot x axis label": "Expected -Log10(P-Value)",
            "hover content": [
              "Region",
              "P-Value: Low Freq"
            ],
            "height": 150
          }
        ]
      }
    }
  ]
}
